package com.featuredeliveryintelligence.fdi.runtime;
import java.util.*;
public final class ProductKnowledgeMaintenance {private ProductKnowledgeMaintenance(){} public static Map<String,Object> createDraft(Map<String,Object>candidate,String proposer,List<String>refs){if(proposer==null||proposer.isBlank()||refs.isEmpty())throw new RuntimeContractException("proposer and source refs are required");Map<String,Object>d=RuntimeMaps.copy(candidate);d.put("publication_state","DRAFT");d.put("validity_state","NOT_APPLICABLE");d.put("publication_policy","HUMAN_APPROVAL");d.put("source_refs",List.copyOf(refs));d.put("proposed_by",proposer);return d;} public static Map<String,Object> publish(Map<String,Object>draft,String actor,Set<String>publishers){if(!"DRAFT".equals(draft.get("publication_state"))||!Objects.equals(actor,draft.get("owner"))||!publishers.contains(actor))throw new RuntimeContractException("accountable publication authority is required");Map<String,Object>p=RuntimeMaps.copy(draft);p.put("publication_state","PUBLISHED");p.put("validity_state","ACTIVE");p.put("published_by",actor);return p;} public static Map<String,Object> onboardingRequest(Map<String,Object>gap,String by){String profile=RuntimeMaps.requiredString(gap,"target_profile"),id=RuntimeMaps.requiredString(gap,"gap_id"),reason=RuntimeMaps.requiredString(gap,"reason");if(!Set.of("PA-01","PA-03","PA-05").contains(profile)||by==null||by.isBlank())throw new RuntimeContractException("invalid onboarding request");return Map.of("request_id","maintenance-request:"+id,"status","REQUESTED","action",reason.toLowerCase().contains("missing")?"CREATE":"REFRESH","trigger","HUMAN_REQUEST","target_profile",profile,"reason",reason,"requested_by",by,"may_publish",false);}}
